sys_ui_action.script:
function fetchWeatherData() {
    var city = g_form.getValue('city');
    if (!city || city.trim().length < 2) {
        g_form.addErrorMessage('Please enter a valid city name (at least 2 characters).');
        return;
    }

    g_form.addInfoMessage('Fetching weather data for ' + city + '...');

    var ga = new GlideAjax('x_1850489_weathe_0.WeatherAjax');
    ga.addParam('sysparm_name', 'getWeather');
    ga.addParam('sysparm_city', city.trim());
    ga.getXMLAnswer(function(answer) {
        if (!answer) {
            g_form.addErrorMessage('No response received from weather service. Check ACL and Script Include configuration.');
            return;
        }
        try {
            var result = JSON.parse(answer);
            if (result.success) {
                g_form.setValue('temperature', result.temp_c);
                g_form.setValue('condition', result.condition);
                g_form.addInfoMessage('Weather data updated: ' + result.temp_c + '°C, ' + result.condition);
            } else {
                g_form.addErrorMessage('Weather lookup failed: ' + (result.error || 'Unknown error'));
            }
        } catch (e) {
            g_form.addErrorMessage('Error parsing weather response: ' + e.message);
        }
    });
}
